import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();

  // Primary animation root
  const container = new THREE.Group();
  group.add(container);

  // Palette from spec
  const ink = config.intent?.visualSpec?.colors?.ink ?? "#16161d";
  const paper = config.intent?.visualSpec?.colors?.paper ?? "#e8ecf2";
  const accentColor = config.intent?.visualSpec?.colors?.accent ?? "#ff2a38";
  const surfaceStr = config.intent?.visualSpec?.colors?.surface ?? "#0b0b10";

  // --- CARD BODY ---
  // Beautiful dark backplate card (machined metal aesthetic)
  const cardGeo = new THREE.BoxGeometry(2.4, 3.2, 0.08);
  const cardMat = new MeshStandardNodeMaterial({
    color: surfaceStr,
    roughness: 0.55,
    metalness: 0.52,
    clearcoat: 0.15,
    clearcoatRoughness: 0.2
  });
  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, -0.04);
  cardMesh.castShadow = true;
  cardMesh.receiveShadow = true;
  container.add(cardMesh);

  // Accent Frame Border
  const frameGeo = new THREE.BoxGeometry(2.44, 3.24, 0.02);
  const frameMat = new MeshBasicNodeMaterial({
    color: accentColor,
    transparent: true,
    opacity: 0.15
  });
  const frameMesh = new THREE.Mesh(frameGeo, frameMat);
  frameMesh.position.set(0, 0, -0.05);
  container.add(frameMesh);

  // --- CAPTION STRIP TEXT ---
  // Core branding caption utilizing JetBrains Mono details
  const labelMono = ctx.fontAtlas.createText('N° 01 / COLLECTIBLE ENGINE', {
    fontSize: 10,
    color: accentColor,
    align: 'center'
  });
  labelMono.position.set(0, -1.25, 0.06);
  container.add(labelMono);

  const labelDisplay = ctx.fontAtlas.createText('GEAR ASSEMBLY', {
    fontSize: 14,
    color: paper,
    align: 'center'
  });
  labelDisplay.position.set(0, -1.0, 0.06);
  container.add(labelDisplay);

  // --- GLB MODEL RETRIEVAL & ROTATION ---
  let loadedMesh = null;
  let rotationTween = null;
  const meshUrl = config.meshUrl || '/prism-mock/orrery/meshes/gear-a.glb';

  ctx.glbLoader.loadGLB(meshUrl)
    .then((gltf) => {
      loadedMesh = gltf.scene;

      // Normalization scaling
      const box = new THREE.Box3().setFromObject(loadedMesh);
      const size = box.getSize(new THREE.Vector3());
      const maxDim = Math.max(size.x, size.y, size.z);
      const scaleFactor = 1.2 / (maxDim || 1);
      loadedMesh.scale.setScalar(scaleFactor);

      // Position in the upper area of the card
      loadedMesh.position.set(0, 0.35, 0.15);

      // Inject professional PBR look targeting dark atelier values
      loadedMesh.traverse((child) => {
        if (child.isMesh) {
          child.castShadow = true;
          child.receiveShadow = true;
          if (child.material) {
            child.material.metalness = 0.55;
            child.material.roughness = 0.45;
            child.material.color.set(paper);
          }
        }
      });

      container.add(loadedMesh);

      // Steady cinematic gear rotation
      rotationTween = gsap.to(loadedMesh.rotation, {
        y: Math.PI * 2,
        duration: 16,
        repeat: -1,
        ease: "none"
      });
    })
    .catch((err) => {
      // Elegant fallback representation torus if loading fails
      const fallbackGeo = new THREE.TorusGeometry(0.4, 0.12, 16, 64);
      const fallbackMat = new MeshStandardNodeMaterial({
        color: paper,
        metalness: 0.55,
        roughness: 0.4
      });
      loadedMesh = new THREE.Mesh(fallbackGeo, fallbackMat);
      loadedMesh.position.set(0, 0.35, 0.15);
      container.add(loadedMesh);

      rotationTween = gsap.to(loadedMesh.rotation, {
        z: Math.PI * 2,
        duration: 10,
        repeat: -1,
        ease: "none"
      });
    });

  // --- LOCAL LIGHTS ---
  // Highlighting key dimensions of the metallic artifact
  const nodeLocalLight = new THREE.DirectionalLight(paper, 1.2);
  nodeLocalLight.position.set(2, 3, 4);
  container.add(nodeLocalLight);

  const localRimLight = new THREE.DirectionalLight(accentColor, 0.8);
  localRimLight.position.set(-2, -1, -2);
  container.add(localRimLight);

  // Contact shadow representation plane below card
  const shadowGeo = new THREE.PlaneGeometry(2.0, 0.3);
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.5
  });
  const contactShadow = new THREE.Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, -1.65, -0.1);
  container.add(contactShadow);

  // --- INTERACTIVITY HANDLERS ---
  let hoverTimeline = null;

  const onPointerOver = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();

    // Subtle rise-in lift (0.15 scene units)
    hoverTimeline.to(container.position, {
      y: 0.15,
      z: 0.12,
      duration: 0.4,
      ease: "power2.out"
    });
    // Accentuate the red edge alignment glow
    hoverTimeline.to(frameMat, {
      opacity: 0.8,
      duration: 0.3
    }, 0);
  };

  const onPointerOut = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();

    // Graceful descent back to original profile
    hoverTimeline.to(container.position, {
      y: 0,
      z: 0,
      duration: 0.4,
      ease: "power2.out"
    });
    hoverTimeline.to(frameMat, {
      opacity: 0.15,
      duration: 0.4
    }, 0);
  };

  const onClick = () => {
    // Elegant tactile spring sequence
    gsap.timeline()
      .to(container.scale, { x: 0.96, y: 0.96, z: 0.96, duration: 0.1, ease: "power2.out" })
      .to(container.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: "back.out(2)" });

    ctx.emit('hub-home.select', { id: config.id });
  };

  // Bind parameters to interface runtime
  group.userData = {
    handlers: {
      pointerover: onPointerOver,
      pointerout: onPointerOut,
      click: onClick
    },
    cleanup: () => {
      if (rotationTween) rotationTween.kill();
      if (hoverTimeline) hoverTimeline.kill();
      cardGeo.dispose();
      cardMat.dispose();
      frameGeo.dispose();
      frameMat.dispose();
      shadowGeo.dispose();
      shadowMat.dispose();
    }
  };

  return group;
}
